#[cfg(test)]
mod tests {
    use rigorix_engine::effect_commitment::domain::{ResolverIdentity, ResolverKind};

    #[test]
    fn test_resolveridentity_is_defined() {
        let provider = ResolverIdentity::new("stripe-readback", ResolverKind::Provider, "digest");
        assert!(provider.is_authorized());
        assert_eq!(provider.resolver_id, "stripe-readback");

        let operator = ResolverIdentity::new("ops-1", ResolverKind::ExternalOperator, "digest");
        assert!(operator.is_authorized());

        // F4: the parties that provably cannot know are representable so the
        // policy can reject them explicitly.
        let dispatcher =
            ResolverIdentity::new("dispatch-loop", ResolverKind::DispatchingProcess, "digest");
        assert!(!dispatcher.is_authorized());
        let agent = ResolverIdentity::new("agent", ResolverKind::Agent, "digest");
        assert!(!agent.is_authorized());
    }

    #[test]
    fn test_resolveridentity_interacts_with_none() {
        let resolver = ResolverIdentity::new("stripe-readback", ResolverKind::Provider, "digest");
        let json = serde_json::to_string(&resolver).unwrap();
        assert!(json.contains("\"kind\":\"provider\""));
        let round_trip: ResolverIdentity = serde_json::from_str(&json).unwrap();
        assert_eq!(round_trip, resolver);
    }
}
